from typing import List

def maximumSubarrayXor(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    # S[d][k] is the XOR score of a subarray starting at index k with length d+1.
    # The difference between end and start index is d (0 <= d < n).
    S = [[0] * n for _ in range(n)]

    for k in range(n):
        S[0][k] = nums[k]

    for d in range(1, n):
        # L is the least significant bit of d (e.g., if d=3 (binary 011), L=1).
        L = d & -d
        prev_d = d ^ L
        for k in range(n - d):
            S[d][k] = S[prev_d][k] ^ S[prev_d][k + L]

    # dp[i][j] will store the maximum XOR score for any subarray entirely within [i, j].
    dp = [[0] * n for _ in range(n)]
    for d in range(n):
        for k in range(n - d):
            # The score of a subarray starting at k and ending at k+d.
            dp[k][k + d] = S[d][k]

    # Propagate the maximum values to cover all subarrays within [i, j].
    # We use dynamic programming: dp[i][j] = max(score of nums[i..j], 
    # max score in [i+1, j], max score in [i, j-1]).
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if i + 1 <= j:
                dp[i][j] = max(dp[i][j], dp[i+1][j])
            if j > i:
                dp[i][j] = max(dp[i][j], dp[i][j-1])

    results = []
    for l, r in queries:
        results.append(dp[l][r])

    return results

