    # 我們用一個陣列來儲存每個數值對應的最小索引，找不到則為 -1
    max_val = 100000
    res_map = [-1] * (max_val + 1)
    for val, idx in min_index.items():
        res_map[val] = idx

    # 對於每個 group，我們需要找到一個元素 x，使得 group % x == 0
    # 且 x 的索引最小。這等同於在所有約數中找 res_map 值最小的。
    ans = []
    for g in groups:
        best_idx = -1
        # 遍歷 g 的所有約數
        for i in range(1, int(g**0.5) + 1):
            if g % i == 0:
                # 檢查約數 i
                if res_map[i] != -1:
                    if best_idx == -1 or res_map[i] < best_idx:
                        best_idx = res_map[i]
                # 檢查對應的約數 g // i
                other = g // i
                if res_map[other] != -1:
                    if best_idx == -1 or res_map[other] < best_idx:
                        best_idx = res_map[other]
        ans.append(best_idx)

