    # Let's stick to the standard DP but skip the initial (0,0) product 1
    dp = {} # (sum, parity) -> set of products
    for x in nums:
        updates = []
        # Option A: Start a new subsequence with just x
        if x <= limit: updates.append(((x, 1), {x}))
        # Option B: Append x to existing subsequences
        for (s, p), prods in dp.items():
            ns = s + x if p == 0 else s - x
            np = 1 - p
            new_p_set = set()
            for pr in prods:
                res = pr * x
                if res <= limit: new_p_set.add(res)
            if new_p_set: updates.append(((ns, np), new_p_set))

        for key, val in updates:
            if key not in dp: dp[key] = set()
            dp[key].update(val)

    ans = -1
    for (s, p), prods in dp.items():
        if s == k:
            ans = max(ans, max(prods))
    return ans
