from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[(current_sum, current_parity)] = set of products
    # parity 0 means the next element added will be at an even index (positive sign)
    # parity 1 means the next element added will be at an odd index (negative sign)
    # Actually, let's redefine:
    # parity 0: The last element was added with a positive sign (even index). Next is negative.
    # parity 1: The last element was added with a negative sign (odd index). Next is positive.
    # Special case: Empty subsequence has sum 0, but we need non-empty.

    dp = {} # (current_sum, next_sign) -> set of products
    # next_sign: 1 for positive contribution, -1 for negative contribution

    for x in nums:
        new_entries = []
        # Start a new subsequence with x. It is always at index 0 (positive).
        if x <= limit:
            # After picking x (even index), the next pick will be odd (negative sign)
            new_entries.append(((x, -1), {x}))

        # Extend existing subsequences
        for (s, next_sign), prods in dp.items():
            ns = s + (next_sign * x)
            np = 1 if next_sign == -1 else -1

            # Constraint check: sum can be large, but nums[i] <= 12 and len(nums) <= 150
            # Max possible sum is 12*150 = 1800. k is up to 10^5.
            # If abs(ns) > 2000, it's unlikely to reach a small k unless we have many negatives.
            # However, since nums[i] >= 0, the sum range is actually limited.
            if abs(ns) <= 3000:
                new_prods = set()
                for pr in prods:
                    res_p = pr * x
                    if res_p <= limit:
                        new_prods.add(res_p)
                if new_prods:
                    new_entries.append(((ns, np), new_prods))

        for (s, sign), prods in new_entries:
            if (s, sign) not in dp:
                dp[(s, sign)] = set()
            dp[(s, sign)].update(prods)

    max_p = -1
    for (s, sign), prods in dp.items():
        if s == k:
            for pr in prods:
                if pr > max_p:
                    max_p = pr

    return max_p
