def separateSquares(squares: List[List[int]]) -> float:
    total_area = 0.0
    min_y = float('inf')
    max_y = float('-inf')

    for _, y, l in squares:
        total_area += float(l * l)
        if y < min_y: min_y = float(y)
        if y + l > max_y: max_y = float(y + l)

    target = total_area / 2.0
    low = min_y
    high = max_y

    # Binary search for the horizontal line y-coordinate
    for _ in range(100):
        mid = (low + high) / 2.0
        current_below = 0.0
        for _, y, l in squares:
            if mid > y:
                h_below = min(float(l), mid - y)
                # The area of the square below height 'mid' is width * height_below
                # Since it's a square with side length l, width is always l.
                current_below += h_below * float(l)

        if current_below < target:
            low = mid
        else:
            high = mid

    return low
